#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/routine (original artwork for this project).
Run once: python3 scripts/draw-routine-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'routine'
OUT.mkdir(parents=True, exist_ok=True)

ROOM = lambda wall='#fde9c9', floor='#c99a6b': f'<rect width="64" height="64" rx="8" fill="{wall}"/><rect x="0" y="46" width="64" height="18" fill="{floor}"/>'
PERSON = lambda x, y, shirt='#d62828', skin='#f5c6a5', hair='#5a2d1a': (
    f'<circle cx="{x}" cy="{y}" r="5" fill="{skin}"/><path d="M{x - 5} {y - 1} Q{x} {y - 8} {x + 5} {y - 1}" fill="{hair}"/>'
    f'<rect x="{x - 5}" y="{y + 5}" width="10" height="13" rx="3" fill="{shirt}"/>'
    f'<rect x="{x - 4}" y="{y + 18}" width="3" height="9" fill="#2b3a67"/><rect x="{x + 1}" y="{y + 18}" width="3" height="9" fill="#2b3a67"/>')
CLOCK = lambda x, y, txt: f'<rect x="{x}" y="{y}" width="18" height="9" rx="2" fill="#222"/><text x="{x + 9}" y="{y + 7}" font-family="monospace" font-size="6.5" fill="#7cff6b" text-anchor="middle">{txt}</text>'
BED = lambda: '<rect x="6" y="30" width="52" height="16" rx="3" fill="#8d5524"/><rect x="8" y="24" width="48" height="10" rx="3" fill="#4d96ff"/><rect x="10" y="20" width="14" height="8" rx="2" fill="#fff"/>'
SUN = '<circle cx="52" cy="12" r="6" fill="#ffd54a"/>'
MOON = '<path d="M50 6 A8 8 0 1 0 58 16 A6 6 0 1 1 50 6Z" fill="#fff59d"/>'
WINDOW = lambda x=38, y=8, night=False: f'<rect x="{x}" y="{y}" width="18" height="16" rx="2" fill="{"#1a237e" if night else "#8ecae6"}" stroke="#fff" stroke-width="2"/><line x1="{x + 9}" y1="{y}" x2="{x + 9}" y2="{y + 16}" stroke="#fff" stroke-width="2"/>'

ICONS = {
    'get-up': ROOM() + WINDOW() + SUN + BED() + '<circle cx="24" cy="20" r="5" fill="#f5c6a5"/><path d="M19 19 Q24 12 29 19" fill="#5a2d1a"/><path d="M14 30 L22 26 M34 30 L26 26" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><rect x="18" y="25" width="12" height="8" rx="2" fill="#ffb4a2"/>' + CLOCK(40, 34, '7:00') + '<path d="M60 30 L62 26 M60 38 L62 42" stroke="#e63946" stroke-width="2"/>',
    'take-a-shower': ROOM('#cfe8ff', '#8ecae6') + '<rect x="24" y="4" width="4" height="10" fill="#9e9e9e"/><rect x="18" y="12" width="16" height="4" rx="2" fill="#9e9e9e"/>' + ''.join(f'<line x1="{20 + i * 3}" y1="17" x2="{19 + i * 3}" y2="30" stroke="#4d96ff" stroke-width="1.5" stroke-linecap="round"/>' for i in range(5)) + PERSON(26, 24, '#f5c6a5') + '<rect x="0" y="44" width="64" height="8" fill="#fff"/><circle cx="12" cy="38" r="3" fill="#fff" opacity=".9"/><circle cx="46" cy="34" r="4" fill="#fff" opacity=".9"/><circle cx="52" cy="42" r="3" fill="#fff" opacity=".9"/>',
    'get-dressed': ROOM() + '<rect x="4" y="8" width="18" height="34" rx="2" fill="#8d5524"/><rect x="6" y="10" width="14" height="30" fill="#c99a6b"/><path d="M8 14 L18 14 L16 26 L10 26Z" fill="#4d96ff"/><path d="M8 28 L18 28 L16 38 L10 38Z" fill="#2e7d32"/>' + PERSON(40, 16, '#fff', hair='#ffd54a') + '<path d="M40 22 L40 32" stroke="#d62828" stroke-width="3"/><path d="M35 22 L45 22" stroke="#d62828" stroke-width="2"/>',
    'leave-home': ROOM('#a8d5a2', '#7cb342') + '<rect x="4" y="10" width="26" height="40" fill="#c97b63"/><rect x="10" y="20" width="12" height="30" fill="#5a2d1a"/><circle cx="20" cy="36" r="1.5" fill="#ffd54a"/><path d="M4 10 L17 2 L30 10Z" fill="#8d5524"/>' + PERSON(44, 22, '#d62828') + '<rect x="50" y="34" width="8" height="10" rx="1" fill="#5a2d1a"/><path d="M36 30 L28 30" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>',
    'start-work': ROOM('#e8eaf6', '#9fa8da') + '<rect x="6" y="32" width="52" height="4" fill="#8d5524"/><rect x="26" y="12" width="26" height="18" rx="2" fill="#222"/><rect x="28" y="14" width="22" height="14" fill="#4d96ff"/><rect x="36" y="30" width="6" height="3" fill="#555"/><rect x="24" y="36" width="18" height="3" rx="1" fill="#ccc"/>' + PERSON(14, 14, '#fff') + '<ellipse cx="50" cy="40" rx="4" ry="3" fill="#fff"/><rect x="47" y="34" width="6" height="6" fill="#fff" stroke="#8d5524"/>' + CLOCK(6, 4, '9:00'),
    'go-grocery-shopping': ROOM('#fff3e0', '#e0e0e0') + ''.join(f'<rect x="{4 + i * 8}" y="{8 + (i % 2) * 6}" width="6" height="8" rx="1" fill="{c}"/>' for i, c in enumerate(['#e63946', '#ffd54a', '#4caf50', '#4d96ff', '#ff8f00', '#9c27b0', '#2e7d32'])) + '<rect x="30" y="30" width="26" height="14" rx="2" fill="none" stroke="#555" stroke-width="2.5"/><path d="M24 24 L30 30" stroke="#555" stroke-width="2.5"/><circle cx="34" cy="48" r="3" fill="#333"/><circle cx="52" cy="48" r="3" fill="#333"/><rect x="33" y="24" width="8" height="8" rx="1" fill="#ffd54a"/><rect x="43" y="26" width="10" height="6" rx="1" fill="#4caf50"/>' + PERSON(14, 22, '#4d96ff'),
    'listen-to-the-radio': ROOM() + '<rect x="6" y="26" width="26" height="18" rx="3" fill="#8d5524"/><circle cx="14" cy="35" r="5" fill="#333"/><circle cx="14" cy="35" r="2" fill="#999"/><rect x="22" y="30" width="8" height="3" fill="#ccc"/><rect x="22" y="36" width="8" height="3" fill="#ccc"/><line x1="28" y1="26" x2="34" y2="14" stroke="#555" stroke-width="2"/><path d="M36 22 Q42 26 36 30 M40 18 Q50 26 40 34" stroke="#4d96ff" stroke-width="2" fill="none"/>' + PERSON(50, 22, '#ff8f00') + '<rect x="40" y="44" width="22" height="6" rx="3" fill="#b71c1c"/>',
    'do-housework': ROOM() + '<rect x="6" y="36" width="16" height="10" rx="3" fill="#e63946"/><circle cx="10" cy="47" r="2.5" fill="#333"/><circle cx="18" cy="47" r="2.5" fill="#333"/><path d="M14 36 Q16 20 28 24" stroke="#555" stroke-width="2.5" fill="none"/>' + PERSON(36, 18, '#fff', hair='#ffd54a') + '<path d="M31 26 L28 24" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><rect x="48" y="30" width="12" height="16" fill="#8d5524"/><rect x="50" y="26" width="8" height="4" fill="#fff"/>',
    'finish-work': ROOM('#e8eaf6', '#9fa8da') + WINDOW(40, 6, night=True) + MOON + '<rect x="6" y="34" width="34" height="4" fill="#8d5524"/><rect x="10" y="20" width="14" height="10" rx="1" fill="#222"/><rect x="11" y="21" width="12" height="8" fill="#111"/>' + PERSON(48, 24, '#d62828') + '<rect x="52" y="38" width="8" height="8" rx="1" fill="#5a2d1a"/><path d="M42 32 L36 34" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>' + CLOCK(6, 6, '6:00'),
    'get-home': ROOM('#5c6bc0', '#7cb342') + MOON + '<rect x="18" y="16" width="30" height="34" fill="#c97b63"/><rect x="28" y="30" width="10" height="20" fill="#5a2d1a"/><rect x="21" y="20" width="8" height="7" fill="#fff59d"/><rect x="37" y="20" width="8" height="7" fill="#fff59d"/><path d="M16 16 L33 6 L50 16Z" fill="#8d5524"/>' + PERSON(10, 22, '#d62828') + '<circle cx="41" cy="24" r="2.5" fill="#f5c6a5"/><path d="M40 27 L42 27 L45 22" stroke="#f5c6a5" stroke-width="1.5" fill="none"/>',
    'go-to-bed': ROOM('#283593', '#5c6bc0') + WINDOW(40, 6, night=True) + MOON + BED() + '<circle cx="18" cy="24" r="4" fill="#f5c6a5"/><path d="M14 23 Q18 18 22 23" fill="#5a2d1a"/><path d="M15 25 L21 25" stroke="#5a2d1a" stroke-width="1"/><path d="M48 12 L50 8 L52 12" stroke="#fff" fill="none"/><text x="30" y="14" font-family="sans-serif" font-size="8" fill="#fff" font-style="italic">z z</text>',
    'read-a-book': ROOM('#fde9c9', '#8d5524') + '<rect x="6" y="30" width="52" height="16" rx="3" fill="#8d5524"/><rect x="8" y="24" width="48" height="10" rx="3" fill="#d62828"/><rect x="8" y="16" width="12" height="8" rx="2" fill="#fff"/>' + '<circle cx="42" cy="14" r="5" fill="#f5c6a5"/><path d="M37 13 Q42 6 47 13" fill="#5a2d1a"/><rect x="36" y="19" width="12" height="7" rx="2" fill="#ffb4a2"/><path d="M30 22 L42 26 L54 22 L54 30 L42 34 L30 30Z" fill="#fff" stroke="#8d5524"/><line x1="42" y1="26" x2="42" y2="34" stroke="#8d5524"/>' + CLOCK(40, 38, '11:00') + '<rect x="4" y="4" width="8" height="12" rx="1" fill="#ffd54a"/><rect x="6" y="16" width="4" height="8" fill="#555"/>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
